productRulesUsed:
.sr-figure-media {
  --ld-figure-ink: var(--sr-ink);
  --ld-figure-muted: var(--sr-ink-soft);
  --ld-figure-accent: var(--sr-ink);
  --ld-figure-accent-soft: var(--sr-ink-dim);
  --ld-figure-grid: var(--sr-line);
  --ld-figure-paper: var(--sr-white);
  position: relative;
  display: block;
  margin: 0 auto;
  width: fit-content;
  max-width: min(100%, 30em);
}

.sr-figure-media svg,
.sr-figure-media img,
.sr-figure-vector {
  display: block;
  width: 100%;
  max-width: 100%;
  height: auto;
}

.sr-read-fig[data-figure-layout="scroll"],
.sr-ex-fig[data-figure-layout="scroll"] {
  overflow-x: auto;
  overflow-y: hidden;
  scrollbar-width: thin;
}
